// =========================================================
//    DATA — one object per direction. Fill in 02–07 the same
//    shape as 01 once you have the sketch crop + Illustrator
//    export + a renderLive() for that mark's own motion idea.
//    =========================================================

function renderPixlBloomMark(container) {
  container.innerHTML = `
    <div class="live-wrap">
      <svg viewBox="0 0 400 380" xmlns="http://www.w3.org/2000/svg">
        <g id="live-cells">
          <rect class="cell cell-ink" x="0" y="20" width="90" height="150"/>
          <rect class="cell cell-paper" x="90" y="20" width="90" height="150"/>
          <rect class="cell cell-ink" x="0" y="180" width="90" height="150"/>
          <rect class="cell cell-paper" x="90" y="180" width="90" height="150"/>
        </g>
        <g id="live-bowls">
          <circle cx="245" cy="115" r="100"/>
          <circle cx="245" cy="250" r="100"/>
        </g>
      </svg>
      <div class="wordmark"><span class="big">PixlBloom</span><span class="small">N&nbsp;&nbsp;Y&nbsp;&nbsp;C</span></div>
    </div>`;

  gsap.set("#live-cells .cell", { opacity: 0, scale: 0.6, transformOrigin: "center" });
  gsap.set("#live-bowls circle", { scale: 0, transformOrigin: "center" });

  gsap
    .timeline()
    .to("#live-cells .cell", { opacity: 1, scale: 1, duration: 0.5, stagger: 0.08, ease: "back.out(2)" })
    .to("#live-bowls circle", { scale: 1, duration: 0.7, stagger: 0.12, ease: "elastic.out(1,0.6)" }, "<0.1")
    .call(() => {
      gsap.to("#live-bowls circle", {
        scale: 1.03,
        duration: 2.6,
        repeat: -1,
        yoyo: true,
        ease: "sine.inOut",
        stagger: { each: 0.4, yoyo: true },
      });
      gsap.utils.toArray("#live-cells .cell").forEach((cell, i) => {
        gsap.to(cell, {
          opacity: 0.55,
          duration: 0.9 + Math.random() * 0.6,
          repeat: -1,
          yoyo: true,
          ease: "sine.inOut",
          delay: i * 0.6 + Math.random(),
        });
      });
    });
}

const directions = [
  {
    title: "Geometry Meets Organic Form",
    real: true,
    sketchSrc:
      "data:image/jpeg;base64,",
    artboardSrc:
      "data:image/png;base64,",
    captionSketch: "charcoal pencil — the cluster I kept redrawing",
    captionArtboard: "rebuilt in Illustrator, flat vector",
    captionMotion: "now it's live — real SVG, not a video",
    renderLive: renderPixlBloomMark,
    notes: `<p>This direction came out of the pixel/checkerboard doodles scattered across the first sketch page — building the letterform out of a small grid rather than one continuous stroke.</p>
            <p>The animation tests a "still loading" behavior: pixel cells flicker at slightly different rates, like the mark is assembling itself, while the two bowls breathe gently so it never feels static.</p>
            <p>Replace this with your own notes — what you were testing, what you'd cut, what surprised you.</p>`,
  },
  { title: "Direction 02", real: false, notes: `<p>Add your notes for direction 02 here.</p>` },
  { title: "Direction 03", real: false, notes: `<p>Add your notes for direction 03 here.</p>` },
  { title: "Direction 04", real: false, notes: `<p>Add your notes for direction 04 here.</p>` },
  { title: "Direction 05", real: false, notes: `<p>Add your notes for direction 05 here.</p>` },
  { title: "Direction 06", real: false, notes: `<p>Add your notes for direction 06 here.</p>` },
  { title: "Direction 07", real: false, notes: `<p>Add your notes for direction 07 here.</p>` },
];

/* ---------- build the deck DOM from the data ---------- */
const track = document.getElementById("track");
const railEl = document.getElementById("rail");

directions.forEach((d, i) => {
  const slide = document.createElement("section");
  slide.className = "slide";
  slide.id = "slide-" + i;

  const sketchInner = d.real
    ? `<img src="${d.sketchSrc}" alt="Sketch crop for ${d.title}">`
    : `<p>Drop in the cropped sketch for ${d.title}.</p>`;
  const artboardInner = d.real
    ? `<span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><img src="${d.artboardSrc}" alt="Illustrator artboard for ${d.title}">`
    : `<span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><p>Drop in the Illustrator export for ${d.title}.</p>`;

  slide.innerHTML = `
    <div class="slide-head">
      <p><span class="num">${String(i + 1).padStart(2, "0")}</span>${d.title}</p>
      <span class="dotted-rule"></span>
    </div>
    <div class="panels">
      <figure class="panel">
        <div class="panel-frame sketch ${d.real ? "" : "placeholder"}">${sketchInner}</div>
        <figcaption><span class="mono num">fig. 1</span><span class="mono desc">${d.real ? d.captionSketch : "add sketch crop"}</span></figcaption>
      </figure>
      <figure class="panel">
        <div class="panel-frame artboard ${d.real ? "" : "placeholder"}">${artboardInner}</div>
        <figcaption><span class="mono num">fig. 2</span><span class="mono desc">${d.real ? d.captionArtboard : "add Illustrator export"}</span></figcaption>
      </figure>
    </div>
    <div class="stage">
      <div class="stage-body ${d.real ? "" : "placeholder"}">
        <button class="mono read-more notes-corner" data-i="${i}">Notes on this direction</button>
        ${
          d.real
            ? `<div class="live-slot" id="stage-${i}"></div>
             <button class="icon-btn replay-btn" data-i="${i}" aria-label="Replay animation">
               <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 1 2.6 6.3"/><path d="M3 21v-6h6"/></svg>
               <span class="tooltip">Replay animation</span>
             </button>`
            : `<p>Motion behavior for ${d.title} — add the animation idea and I'll build it the same way as direction 01.</p>`
        }
      </div>
      <div class="stage-caption">
        <span class="mono"><span class="num">fig. 3</span> — ${d.real ? d.captionMotion : "add motion idea"}. <button class="mono read-more inline-notes" data-i="${i}">Notes on this direction</button></span>
      </div>
    </div>
  `;
  track.appendChild(slide);

  const railBtn = document.createElement("button");
  railBtn.textContent = String(i + 1).padStart(2, "0");
  railBtn.dataset.i = i;
  if (i === 0) railBtn.classList.add("active");
  railBtn.addEventListener("click", () => gotoSlide(i));
  railEl.appendChild(railBtn);
});

document.querySelectorAll(".read-more").forEach((btn) => {
  btn.addEventListener("click", () => openPanel(Number(btn.dataset.i)));
});
document.querySelectorAll(".replay-btn").forEach((btn) => {
  btn.addEventListener("click", () => {
    const i = Number(btn.dataset.i);
    directions[i].renderLive(document.getElementById("stage-" + i));
  });
});

/* ---------- Observer-driven deck navigation ---------- */
gsap.registerPlugin(Observer);

function measureHeader() {
  const h = document.getElementById("project-header").offsetHeight;
  document.documentElement.style.setProperty("--header-h", h + "px");
}
measureHeader();

const slides = gsap.utils.toArray(".slide");
const railButtons = gsap.utils.toArray(".rail button");
const hint = document.getElementById("hint");
let current = 0;
let animating = false;
let panelOpen = false;

// Decided once at load: under ~680px we ditch the deck entirely and let
// the page scroll normally (see the matching CSS media query). Above
// that, the horizontal Observer-driven deck runs as before.
const MOBILE_LAYOUT = window.innerWidth <= 680;

function setActiveRail(i) {
  railButtons.forEach((b, idx) => b.classList.toggle("active", idx === i));
}

function gotoSlide(index) {
  if (index < 0 || index > slides.length - 1 || animating) return;
  closePanel();
  animating = true;
  current = index;
  setActiveRail(index);
  gsap.to(track, {
    x: -index * window.innerWidth,
    duration: 0.85,
    ease: "power3.inOut",
    onComplete: () => {
      animating = false;
      playDirection(index);
    },
  });
  if (index > 0) gsap.to(hint, { opacity: 0, duration: 0.4 });
}

function playDirection(i) {
  const d = directions[i];
  if (d.real) d.renderLive(document.getElementById("stage-" + i));
}

if (!MOBILE_LAYOUT) {
  Observer.create({
    target: window,
    type: "wheel,touch,pointer",
    wheelSpeed: -1,
    tolerance: 8,
    preventDefault: true,
    onUp: () => {
      if (!panelOpen) gotoSlide(current - 1);
    },
    onDown: () => {
      if (!panelOpen) gotoSlide(current + 1);
    },
    onLeft: () => {
      if (!panelOpen) gotoSlide(current - 1);
    },
    onRight: () => {
      if (!panelOpen) gotoSlide(current + 1);
    },
  });
  window.addEventListener("keydown", (e) => {
    if (panelOpen) {
      if (e.key === "Escape") closePanel();
      return;
    }
    if (e.key === "ArrowRight" || e.key === "ArrowDown" || e.key === "PageDown") gotoSlide(current + 1);
    if (e.key === "ArrowLeft" || e.key === "ArrowUp" || e.key === "PageUp") gotoSlide(current - 1);
  });
  window.addEventListener("resize", () => {
    measureHeader();
    gsap.set(track, { x: -current * window.innerWidth });
  });
} else {
  // Mobile: every direction is already visible in the normal page flow,
  // so just render each real direction's animation once, up front.
  directions.forEach((d, i) => {
    if (d.real) d.renderLive(document.getElementById("stage-" + i));
  });
}

/* ---------- notes panel ---------- */
const panel = document.getElementById("notes-panel");
const overlay = document.getElementById("panel-overlay");
function openPanel(i) {
  const d = directions[i];
  document.getElementById("panel-num").textContent = String(i + 1).padStart(2, "0") + " — notes";
  document.getElementById("panel-title").textContent = d.title;
  document.getElementById("panel-body").innerHTML = d.notes;
  panel.classList.add("open");
  overlay.classList.add("open");
  panelOpen = true;
}
function closePanel() {
  panel.classList.remove("open");
  overlay.classList.remove("open");
  panelOpen = false;
}
document.getElementById("panel-close").addEventListener("click", closePanel);
overlay.addEventListener("click", closePanel);

/* ---------- full-sketch lightbox ---------- */
const lightbox = document.getElementById("lightbox-overlay");
function openLightbox() {
  lightbox.classList.add("open");
  panelOpen = true;
}
function closeLightbox() {
  lightbox.classList.remove("open");
  panelOpen = false;
}
document.getElementById("open-lightbox").addEventListener("click", openLightbox);
document.getElementById("lightbox-close").addEventListener("click", closeLightbox);
lightbox.addEventListener("click", (e) => {
  if (e.target === lightbox) closeLightbox();
});
window.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && lightbox.classList.contains("open")) closeLightbox();
});

/* ---------- theme toggle ---------- */
const themeBtn = document.getElementById("theme-toggle");
const sunIcon = document.getElementById("theme-icon-sun");
const moonIcon = document.getElementById("theme-icon-moon");
const themeTooltip = document.getElementById("theme-tooltip");

function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  const isDark = theme === "dark";
  sunIcon.style.display = isDark ? "none" : "block";
  moonIcon.style.display = isDark ? "block" : "none";
  themeTooltip.textContent = isDark ? "Switch to light mode" : "Switch to dark mode";
}

let savedTheme = "light";
try {
  const stored = window.localStorage.getItem("pixlbloom-theme");
  if (stored === "dark" || stored === "light") savedTheme = stored;
} catch (err) {
  /* storage unavailable, default to light */
}
applyTheme(savedTheme);

themeBtn.addEventListener("click", () => {
  const next = document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark";
  applyTheme(next);
  try {
    window.localStorage.setItem("pixlbloom-theme", next);
  } catch (err) {
    /* ignore */
  }
});

/* initial paint (desktop/tablet only — mobile already rendered everything above) */
if (!MOBILE_LAYOUT) {
  gsap.set(track, { x: 0 });
  playDirection(0);
}
